def tsp(cost):
    n = len(cost)
    INF = float('inf')
    dp = [[INF] * n for _ in range(1 << n)]
    dp[1][0] = 0                                # start at city 0
    for mask in range(1, 1 << n):
        for i in range(n):
            if dp[mask][i] == INF:
                continue
            for j in range(n):
                if not (mask & (1 << j)):
                    nm = mask | (1 << j)
                    dp[nm][j] = min(dp[nm][j], dp[mask][i] + cost[i][j])
    full = (1 << n) - 1
    return min(dp[full][i] + cost[i][0] for i in range(n))

class Solution {
public:
    bool canPartitionKSubsets(vector<int>& nums, int k) {
        int total = accumulate(nums.begin(), nums.end(), 0);
        if (total % k) return false;
        int target = total / k, n = nums.size();
        if (*max_element(nums.begin(), nums.end()) > target) return false;
        vector<int> dp(1 << n, -1); dp[0] = 0;
        for (int mask = 0; mask < (1 << n); mask++) {
            if (dp[mask] == -1) continue;
            for (int i = 0; i < n; i++)
                if (!(mask & (1 << i)) && dp[mask] + nums[i] <= target)
                    dp[mask | (1 << i)] = (dp[mask] + nums[i]) % target;
        }
        return dp[(1 << n) - 1] == 0;
    }
};

class Solution:
    def canPartitionKSubsets(self, nums: list[int], k: int) -> bool:
        total = sum(nums)
        if total % k:
            return False
        target, n = total // k, len(nums)
        if max(nums) > target:
            return False
        dp = [-1] * (1 << n)
        dp[0] = 0
        for mask in range(1 << n):
            if dp[mask] == -1:
                continue
            for i in range(n):
                if not (mask >> i & 1) and dp[mask] + nums[i] <= target:
                    dp[mask | (1 << i)] = (dp[mask] + nums[i]) % target
        return dp[(1 << n) - 1] == 0

class Solution {
public:
    int shortestPathLength(vector<vector<int>>& graph) {
        int n = graph.size(), full = (1 << n) - 1;
        vector<vector<bool>> seen(n, vector<bool>(1 << n, false));
        queue<tuple<int,int,int>> q;   // node, mask, dist
        for (int i = 0; i < n; i++) { q.push({i, 1 << i, 0}); seen[i][1 << i] = true; }
        while (!q.empty()) {
            auto [u, mask, d] = q.front(); q.pop();
            if (mask == full) return d;
            for (int v : graph[u]) {
                int nm = mask | (1 << v);
                if (!seen[v][nm]) { seen[v][nm] = true; q.push({v, nm, d + 1}); }
            }
        }
        return 0;
    }
};

from collections import deque
class Solution:
    def shortestPathLength(self, graph):
        n = len(graph)
        full = (1 << n) - 1
        seen = set()
        q = deque()
        for i in range(n):
            q.append((i, 1 << i, 0)); seen.add((i, 1 << i))
        while q:
            u, mask, d = q.popleft()
            if mask == full:
                return d
            for v in graph[u]:
                nm = mask | (1 << v)
                if (v, nm) not in seen:
                    seen.add((v, nm)); q.append((v, nm, d + 1))
        return 0

class Solution {
public:
    int numberWays(vector<vector<int>>& hats) {
        const long long MOD = 1e9 + 7;
        int n = hats.size(), full = (1 << n) - 1;
        vector<vector<int>> hatToPeople(41);
        for (int p = 0; p < n; p++) for (int h : hats[p]) hatToPeople[h].push_back(p);
        vector<long long> dp(1 << n, 0); dp[0] = 1;
        for (int h = 1; h <= 40; h++) {
            vector<long long> ndp = dp;
            for (int mask = 0; mask <= full; mask++) {
                if (!dp[mask]) continue;
                for (int p : hatToPeople[h])
                    if (!(mask & (1 << p))) ndp[mask | (1 << p)] = (ndp[mask | (1 << p)] + dp[mask]) % MOD;
            }
            dp = ndp;
        }
        return (int)dp[full];
    }
};

class Solution:
    def numberWays(self, hats):
        MOD = 10**9 + 7
        n = len(hats)
        full = (1 << n) - 1
        hat_to_people = [[] for _ in range(41)]
        for p in range(n):
            for h in hats[p]:
                hat_to_people[h].append(p)
        dp = [0] * (1 << n)
        dp[0] = 1
        for h in range(1, 41):
            ndp = dp[:]
            for mask in range(full + 1):
                if not dp[mask]:
                    continue
                for p in hat_to_people[h]:
                    if not (mask >> p & 1):
                        ndp[mask | (1 << p)] = (ndp[mask | (1 << p)] + dp[mask]) % MOD
            dp = ndp
        return dp[full]

class Solution {
public:
    int maxStudents(vector<vector<char>>& seats) {
        int m = seats.size(), n = seats[0].size();
        vector<int> good(m, 0);
        for (int i = 0; i < m; i++)
            for (int j = 0; j < n; j++)
                if (seats[i][j] == '.') good[i] |= (1 << j);
        vector<int> prev(1 << n, -1); prev[0] = 0;
        for (int i = 0; i < m; i++) {
            vector<int> cur(1 << n, -1);
            for (int mask = 0; mask < (1 << n); mask++) {
                if ((mask & good[i]) != mask) continue;     // only good seats
                if (mask & (mask << 1)) continue;            // no horizontal neighbour
                for (int pm = 0; pm < (1 << n); pm++) {
                    if (prev[pm] == -1) continue;
                    if ((mask & (pm << 1)) || (mask & (pm >> 1))) continue;
                    cur[mask] = max(cur[mask], prev[pm] + __builtin_popcount(mask));
                }
            }
            prev = cur;
        }
        int best = 0;
        for (int v : prev) best = max(best, v);
        return best;
    }
};

class Solution:
    def maxStudents(self, seats):
        m, n = len(seats), len(seats[0])
        good = [0] * m
        for i in range(m):
            for j in range(n):
                if seats[i][j] == '.':
                    good[i] |= (1 << j)
        prev = {0: 0}
        for i in range(m):
            cur = {}
            for mask in range(1 << n):
                if (mask & good[i]) != mask:
                    continue
                if mask & (mask << 1):
                    continue
                pc = bin(mask).count('1')
                for pm, val in prev.items():
                    if (mask & (pm << 1)) or (mask & (pm >> 1)):
                        continue
                    cur[mask] = max(cur.get(mask, 0), val + pc)
            prev = cur if cur else {0: max(prev.values())}
        return max(prev.values())

class Solution {
public:
    int tsp(vector<vector<int>>& dist) {
        int n = dist.size(), full = (1 << n) - 1;
        const int INF = 1e9;
        vector<vector<int>> dp(1 << n, vector<int>(n, INF));
        for (int i = 0; i < n; i++) dp[1 << i][i] = 0;
        for (int mask = 1; mask <= full; mask++)
            for (int i = 0; i < n; i++) {
                if (dp[mask][i] == INF || !(mask & (1 << i))) continue;
                for (int j = 0; j < n; j++)
                    if (!(mask & (1 << j)))
                        dp[mask | (1 << j)][j] = min(dp[mask | (1 << j)][j], dp[mask][i] + dist[i][j]);
            }
        int best = INF;
        for (int i = 0; i < n; i++) best = min(best, dp[full][i]);
        return best;
    }
};

class Solution:
    def tsp(self, dist):
        n = len(dist)
        full = (1 << n) - 1
        INF = float('inf')
        dp = [[INF] * n for _ in range(1 << n)]
        for i in range(n):
            dp[1 << i][i] = 0
        for mask in range(1, full + 1):
            for i in range(n):
                if dp[mask][i] == INF or not (mask >> i & 1):
                    continue
                for j in range(n):
                    if not (mask >> j & 1):
                        nm = mask | (1 << j)
                        if dp[mask][i] + dist[i][j] < dp[nm][j]:
                            dp[nm][j] = dp[mask][i] + dist[i][j]
        return min(dp[full])
